  [['Manis untuk berbagi','Hampers pilihan untuk orang tersayang.','gift'],['Rasa yang merayakan','Cake kecil, momen besar.','cake'],['Sore yang hangat','Pastry baru matang untuk teman ngobrol.','pastry'],['Warna dalam kotak','Dessert box dengan lapisan menyenangkan.','box'],['Klasik yang dirindu','Kue kering untuk segala suasana.','cookies'],['Segelas jeda','Minuman dingin pelengkap hari.','drink']].forEach(x=>add.run(...x));
