const sessions = new Map();
const money = n => 'Rp' + Number(n || 0).toLocaleString('id-ID');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slug = s => String(s).toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80) || 'item';
const url = s => encodeURIComponent(String(s));
const all = (sql,...args) => db.prepare(sql).all(...args);
const one = (sql,...args) => db.prepare(sql).get(...args);
const arts = ['cookies','cake','pastry','box','gift','drink'];
const statuses = ['Menunggu pembayaran','Menunggu verifikasi','Diproses','Dikirim','Selesai','Dibatalkan'];

